<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{AssetCategory,AssetTransaction,Company,FixedAsset}; use App\Services\{AuthorizationService,OptionalModuleService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class FixedAssetController { public function categories(OptionalModuleService $m){$m->require('fixed_assets');return response()->json(['data'=>AssetCategory::where('tenant_id',app(TenantContext::class)->id())->paginate(50)]);} public function assets(OptionalModuleService $m){$m->require('fixed_assets');return response()->json(['data'=>FixedAsset::where('tenant_id',app(TenantContext::class)->id())->with('transactions')->paginate(25)]);} public function acquire(Request $r,OptionalModuleService $m,AuthorizationService $a){$m->require('fixed_assets');$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'required|uuid','category_id'=>'required|uuid','asset_number'=>'required|alpha_dash|max:50','name'=>'required|string|max:200','acquired_on'=>'required|date','capitalized_on'=>'nullable|date','acquisition_cost'=>'required|numeric|gt:0','residual_value'=>'nullable|numeric|min:0','useful_life_months'=>'required|integer|min:1','depreciation_method'=>'required|in:straight_line']);abort_unless($a->allows($r->user(),$t,'assets.manage',$d['company_id']),403);abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);$asset=DB::transaction(function()use($d,$t,$r){$asset=FixedAsset::create([...$d,'tenant_id'=>$t,'state'=>'capitalized','accumulated_depreciation'=>'0']);AssetTransaction::create(['tenant_id'=>$t,'asset_id'=>$asset->id,'type'=>'acquisition','transaction_date'=>$d['acquired_on'],'amount'=>$d['acquisition_cost'],'created_by'=>$r->user()->id,'description'=>'Asset acquisition']);return $asset;});event(new \App\Events\FixedAssetCapitalized($t,$asset->id,$asset->company_id,(string)$asset->acquisition_cost));return response()->json(['data'=>$asset->load('transactions')],201);} public function depreciate(Request $r,FixedAsset $asset,OptionalModuleService $m,AuthorizationService $a){$m->require('fixed_assets');$t=app(TenantContext::class)->id();abort_unless($asset->tenant_id===$t,404);abort_unless($a->allows($r->user(),$t,'assets.manage',$asset->company_id),403);$d=$r->validate(['transaction_date'=>'required|date']);$remaining=Decimal::sub((string)$asset->acquisition_cost,(string)$asset->residual_value);$monthly=Decimal::div($remaining,(string)$asset->useful_life_months);$next=Decimal::add((string)$asset->accumulated_depreciation,$monthly);if(Decimal::compare($next,$remaining)>0)$monthly=Decimal::sub($remaining,(string)$asset->accumulated_depreciation);if(Decimal::compare($monthly,'0')<=0)throw ValidationException::withMessages(['asset'=>['The asset is fully depreciated.']]);$tx=DB::transaction(function()use($asset,$monthly,$d,$r,$t){$tx=AssetTransaction::create(['tenant_id'=>$t,'asset_id'=>$asset->id,'type'=>'depreciation','transaction_date'=>$d['transaction_date'],'amount'=>$monthly,'created_by'=>$r->user()->id]);$asset->update(['accumulated_depreciation'=>Decimal::add((string)$asset->accumulated_depreciation,$monthly)]);return $tx;});return response()->json(['data'=>$tx],201);} }
